<script setup lang="ts">
import{computed,onMounted,ref}from'vue'
import{descargarCopia,listarCopias,type ArchivoBackup}from'../services/copiasSeguridad'

const principal=ref<ArchivoBackup[]>([]),company=ref<ArchivoBackup[]>([]),companyName=ref('Empresa activa'),database=ref(''),updated=ref(''),query=ref(''),loading=ref(false),downloading=ref(''),error=ref(''),success=ref('')
const principalRows=computed(()=>filter(principal.value)),companyRows=computed(()=>filter(company.value)),total=computed(()=>principal.value.length+company.value.length)
function filter(rows:ArchivoBackup[]){const text=query.value.toLowerCase();return text?rows.filter(x=>x.nombre.toLowerCase().includes(text)):rows}
async function load(){loading.value=true;error.value='';try{const response=await listarCopias();principal.value=response.principal;company.value=response.empresa;companyName.value=response.empresa_nombre||'Empresa activa';database.value=response.base_empresa||'';updated.value=response.ultima_actualizacion||''}catch(e){error.value=e instanceof Error?e.message:'No se pudo consultar las copias de seguridad.'}finally{loading.value=false}}
async function download(item:ArchivoBackup){downloading.value=`${item.origen}:${item.nombre}`;error.value='';success.value='';try{await descargarCopia(item);success.value=`Se inició la descarga de ${item.nombre}.`}catch(e){error.value=e instanceof Error?e.message:'No se pudo descargar la copia de seguridad.'}finally{downloading.value=''}}
function size(item:ArchivoBackup){if(item.tamanio)return item.tamanio;if(item.tamanio_bytes===undefined)return'—';const units=['B','KB','MB','GB'];let value=item.tamanio_bytes,index=0;while(value>=1024&&index<units.length-1){value/=1024;index++}return`${value.toFixed(index?1:0)} ${units[index]}`}
function isDownloading(item:ArchivoBackup){return downloading.value===`${item.origen}:${item.nombre}`}
onMounted(load)
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Sistema / Administrador / Copias de seguridad</nav><header class="hero"><div class="mark">BK</div><div><small>ADMINISTRACIÓN GENERAL</small><h1>Copias de seguridad</h1><p>Respaldos disponibles de la intranet y de la empresa activa.</p></div><div class="metric"><b>{{total}}</b><span>archivos disponibles</span></div><button @click="load">Actualizar lista</button></header><div v-if="success" class="flash good">✓ {{success}}</div><div v-if="error" class="flash bad">{{error}}</div><section class="toolbar"><label>Buscar respaldo<input v-model.trim="query" placeholder="Nombre del archivo"></label><span v-if="updated">Última consulta: {{updated}}</span></section><div v-if="loading" class="empty">Consultando carpetas de respaldo…</div><template v-else><section class="backup-group principal"><header><div class="database">DB</div><div><small>INTRANET</small><h2>Base de datos principal</h2><p>Respaldo de usuarios, empresas y configuración central.</p></div><strong>{{principalRows.length}} archivos</strong></header><div v-if="!principalRows.length" class="empty inner">No hay copias disponibles.</div><article v-for="item in principalRows" :key="item.nombre"><div class="file">7Z</div><div><b>{{item.nombre}}</b><small>{{item.fecha_modificacion||'Fecha no disponible'}}</small></div><span>{{size(item)}}</span><button :disabled="!!downloading" @click="download(item)">{{isDownloading(item)?'Descargando…':'Descargar'}}</button></article></section><section class="backup-group company"><header><div class="database">DB</div><div><small>{{database||'BASE DE EMPRESA'}}</small><h2>{{companyName}}</h2><p>Respaldo operativo correspondiente a la empresa seleccionada.</p></div><strong>{{companyRows.length}} archivos</strong></header><div v-if="!companyRows.length" class="empty inner">No hay copias disponibles.</div><article v-for="item in companyRows" :key="item.nombre"><div class="file">7Z</div><div><b>{{item.nombre}}</b><small>{{item.fecha_modificacion||'Fecha no disponible'}}</small></div><span>{{size(item)}}</span><button :disabled="!!downloading" @click="download(item)">{{isDownloading(item)?'Descargando…':'Descargar'}}</button></article></section><aside><b>Acceso administrativo</b><span>Los respaldos pueden contener información sensible. Descárgalos únicamente en equipos y ubicaciones autorizadas.</span></aside></template></div></template>

<style scoped>
