{width:34px;height:34px;display:grid;place-items:center;border-radius:7px;color:#8f3e43;background:#fae9ea;font-size:.45rem;font-weight:800}.backup-group article b,.backup-group article small{display:block}.backup-group article small{color:#89949a;font-size:.4rem}.backup-group article>span{color:#68777e}.backup-group button:disabled{opacity:.55}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.58rem}.empty.inner{margin:0;background:#fafbfb}aside{margin-top:12px;padding:11px;display:flex;gap:8px;border:1px solid #ead393;border-radius:7px;color:#73591e;background:#fff7df;font-size:.48rem}aside span{margin-left:auto}@media(max-width:650px){.hero{flex-wrap:wrap}.metric{margin-left:0;text-align:left}.toolbar{align-items:stretch;flex-direction:column}.backup-group article{grid-template-columns:38px 1fr auto}.backup-group article>span{display:none}aside{display:block}aside span{display:block;margin-top:4px}}
</style>
